import{_ as s,a as i,o as t,a6 as n}from"./chunks/framework.CJDy2q7X.js";const h=JSON.parse(`{"title":"Get Admin Permissions","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-permissions-gql-all","title":"Full Access Token","description":"A token whose permission mode is All returns the wildcard rather than an expanded key list.","query":"query {\\n  getAdminPermissions {\\n    id\\n    _id\\n    permissionType\\n    permissions\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"getAdminPermissions\\": {\\n      \\"id\\": \\"/api/admin/admin_permissions/permissions\\",\\n      \\"_id\\": \\"permissions\\",\\n      \\"permissionType\\": \\"all\\",\\n      \\"permissions\\": [\\"*\\"]\\n    }\\n  }\\n}\\n"},{"id":"admin-permissions-gql-custom","title":"Custom Access Token","description":"A restricted token returns the explicit ACL keys it was granted, already capped by the owning admin's role.","query":"query {\\n  getAdminPermissions {\\n    id\\n    _id\\n    permissionType\\n    permissions\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"getAdminPermissions\\": {\\n      \\"id\\": \\"/api/admin/admin_permissions/permissions\\",\\n      \\"_id\\": \\"permissions\\",\\n      \\"permissionType\\": \\"custom\\",\\n      \\"permissions\\": [\\"catalog\\", \\"catalog.products\\", \\"sales.orders\\"]\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/navigation/permissions.md","filePath":"api/graphql-api/admin/navigation/permissions.md","lastUpdated":1787290888000}`),o={name:"api/graphql-api/admin/navigation/permissions.md"};function r(a,e,d,c,l,p){return t(),i("div",null,e[0]||(e[0]=[n('<h1 id="get-admin-permissions" tabindex="-1">Get Admin Permissions <a class="header-anchor" href="#get-admin-permissions" aria-label="Permalink to &quot;Get Admin Permissions&quot;">​</a></h1><p>Returns the authenticated token&#39;s effective permissions so you can gate UI up front — show or hide buttons, menus and actions without triggering trial-and-error errors.</p><h2 id="output-fields" tabindex="-1">Output Fields <a class="header-anchor" href="#output-fields" aria-label="Permalink to &quot;Output Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>ID!</td><td>Resource identifier in IRI form, <code>/api/admin/admin_permissions/permissions</code>.</td></tr><tr><td><code>_id</code></td><td>String</td><td>The bare identifier, always the literal <code>permissions</code>.</td></tr><tr><td><code>permissionType</code></td><td>String</td><td>One of <code>all</code>, <code>custom</code>, or <code>same_as_web</code>.</td></tr><tr><td><code>permissions</code></td><td>Iterable</td><td>The granted ACL keys, or <code>[&quot;*&quot;]</code> for full access.</td></tr></tbody></table><p><code>permissions</code> is a JSON scalar — select it as a <strong>bare field</strong>, with no sub-selection.</p><h2 id="permission-modes" tabindex="-1">Permission Modes <a class="header-anchor" href="#permission-modes" aria-label="Permalink to &quot;Permission Modes&quot;">​</a></h2><ul><li><code>all</code> — full access. <code>permissions</code> is the single-element <code>[&quot;*&quot;]</code>, never an expanded list of keys.</li><li><code>custom</code> — <code>permissions</code> lists the explicitly granted ACL keys, frozen onto the token when it was generated.</li><li><code>same_as_web</code> — the token mirrors the owning admin&#39;s current role, so the returned keys change whenever that role changes.</li></ul><p>In every case the effective <code>permissions</code> are capped by the owning admin&#39;s role — a token can never do more than its owner currently can.</p><h2 id="using-the-result" tabindex="-1">Using the Result <a class="header-anchor" href="#using-the-result" aria-label="Permalink to &quot;Using the Result&quot;">​</a></h2><p>Match a key against the <code>permission</code> field of a <a href="/api/graphql-api/admin/navigation/menu.html">menu</a> node, or against the ACL key named on an operation&#39;s page, to decide whether to render its UI.</p><p>Two things to handle:</p><ul><li><strong><code>[&quot;*&quot;]</code> is a wildcard, not a key.</strong> A literal <code>permissions.includes(&#39;sales.orders&#39;)</code> returns false for a full-access token. Branch on <code>permissionType === &#39;all&#39;</code> first.</li><li><strong>Keys are exact, not prefixes.</strong> Holding <code>catalog</code> does not imply <code>catalog.products</code> — the example above lists both because both were granted. Check the exact key an operation requires.</li></ul><p>Gating on this query is advisory. The API re-checks on every call, so a client that skips the check still gets a permission error rather than unauthorized access.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><p>A request without a valid token is rejected by the transport with HTTP <code>401</code> before the GraphQL layer runs. Any valid token can read its own permissions — there is no permission gate on this query.</p>',15)]))}const u=s(o,[["render",r]]);export{h as __pageData,u as default};
